import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Clash 与 Quantumult X 兼容吗？","description":"说明如何把 Quantumult X 的订阅、节点、策略、重写和过滤需求迁移到 Clash iOS。","frontmatter":{"title":"Clash 与 Quantumult X 兼容吗？","description":"说明如何把 Quantumult X 的订阅、节点、策略、重写和过滤需求迁移到 Clash iOS。","head":[["meta",{"name":"keywords","content":"Quantumult X转Clash,圈X转Clash,QuanX订阅,Quantumult X配置,Clash iOS"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"如何把 Quantumult X 配置迁移到 Clash？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"优先添加服务商提供的 Clash / mihomo 订阅，也可以把节点参数整理为 mihomo YAML 或在节点编辑器中添加；策略、重写和过滤需求可使用 Clash 规则与对应功能重新建立。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Quantumult X 的订阅可以用于 Clash 吗？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"服务商通过 HTTPS 订阅地址返回 mihomo YAML 时，可以直接添加到 Clash；单节点参数也可以整理为 YAML 或手动添加。\\"}}]}"]]},"headers":[],"relativePath":"zh/guide/compatibility/quantumult-x.md","filePath":"zh/guide/compatibility/quantumult-x.md","lastUpdated":1785318168000}`),a={name:`zh/guide/compatibility/quantumult-x.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="clash-与-quantumult-x-兼容吗" tabindex="-1">Clash 与 Quantumult X 兼容吗？ <a class="header-anchor" href="#clash-与-quantumult-x-兼容吗" aria-label="Permalink to “Clash 与 Quantumult X 兼容吗？”">​</a></h1><p><strong>常见节点可以继续使用，分流策略可以通过 Clash 规则重新建立。</strong></p><p>Quantumult X 使用独立的<a href="https://github.com/crossutility/Quantumult-X/blob/master/sample.conf" target="_blank" rel="noreferrer">配置与资源语法</a>。迁移到 Clash 时，节点可以通过订阅、mihomo YAML 或节点编辑器继续使用，策略、重写、脚本和过滤需求则可使用对应功能重新建立。</p><h2 id="哪些内容可以继续使用" tabindex="-1">哪些内容可以继续使用？ <a class="header-anchor" href="#哪些内容可以继续使用" aria-label="Permalink to “哪些内容可以继续使用？”">​</a></h2><ul><li>能够返回 mihomo YAML 的订阅地址；</li><li><code>ss://</code>、<code>ssr://</code>、<code>vmess://</code> 等分享链接中记录的节点参数，但需要先转换成 mihomo YAML 或手动填写；</li><li>能够在 Clash 节点编辑器中按参数重新建立的服务器。</li></ul><h2 id="怎么迁移" tabindex="-1">怎么迁移？ <a class="header-anchor" href="#怎么迁移" aria-label="Permalink to “怎么迁移？”">​</a></h2><ol><li>向服务商选择 Clash / mihomo 格式的订阅。</li><li>将该订阅 URL 添加到 Clash；必要时切换订阅 User-Agent。</li><li>根据单节点分享链接或 Base64 列表中的参数，整理为 mihomo YAML 或在节点编辑器中添加。</li><li>使用 Clash 规则重新表达原来的分流需求。</li></ol><h2 id="迁移时需要重新配置的内容" tabindex="-1">迁移时需要重新配置的内容 <a class="header-anchor" href="#迁移时需要重新配置的内容" aria-label="Permalink to “迁移时需要重新配置的内容”">​</a></h2><ul><li>将节点和策略整理为 mihomo YAML；</li><li>使用 Clash 对应功能建立 Rewrite、Filter、Task 与脚本需求；</li><li>将产品专用资源语法转换为 Clash 规则；</li><li>按自己的使用习惯设置 App 偏好。</li></ul><p>协议和参数对应后，同一台服务器可以直接使用。</p><p>返回<a href="/clash.md/zh/guide/compatibility">兼容性总览</a>。</p>`,11)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};